import{_ as s,a as n}from"./chunks/page-management.D5OSBh61.js";import{_ as i,m as l,k as r,q as e,ah as o,B as a}from"./chunks/framework.HEc25T99.js";const P=JSON.parse('{"title":"Pages","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"fr/developers/admin-panel/content-management/pages.md","filePath":"src/fr/developers/admin-panel/content-management/pages.md"}'),c={name:"fr/developers/admin-panel/content-management/pages.md"},d=s+"#light-only",p=n+"#dark-only";function u(g,t,m,h,f,_){return r(),l("div",null,[...t[0]||(t[0]=[e("h1",{id:"pages",tabindex:"-1"},[a("Pages "),e("a",{class:"header-anchor",href:"#pages","aria-label":'Permalink to "Pages"'},"​")],-1),e("p",null,[a("Cette rubrique (repérable dans le menu latéral sous l'intitulé "),e("strong",null,"Sections de page"),a(") gère les pages du site et l'assemblage de leurs sections. Elle correspond côté CLI au groupe "),e("a",{href:"./../../resources/cli.html#creopse-page-alias-pag"},[e("code",null,"creopse page")]),a(".")],-1),e("p",null,[e("img",{src:d,alt:"Pages"}),e("img",{src:p,alt:"Pages"})],-1),o('<h2 id="liste-des-pages" tabindex="-1">Liste des pages <a class="header-anchor" href="#liste-des-pages" aria-label="Permalink to &quot;Liste des pages&quot;">​</a></h2><p>Un champ <strong>Filtrer les pages</strong> permet de rechercher une page par nom dans la liste. En bas de liste :</p><ul><li><strong>Ajouter une page</strong> — crée une nouvelle page (titre par langue, position d&#39;affichage).</li><li><strong>Réorganiser les pages</strong> — modifie l&#39;ordre des pages dans la liste (n&#39;affecte pas leur URL).</li></ul><h2 id="detail-d-une-page" tabindex="-1">Détail d&#39;une page <a class="header-anchor" href="#detail-d-une-page" aria-label="Permalink to &quot;Détail d&#39;une page&quot;">​</a></h2><p>En sélectionnant une page dans la liste :</p><ul><li><strong>Modifier la page</strong> — édite le titre (par langue), le contenu et la position de la page.</li><li><strong>Supprimer</strong> — supprime la page.</li><li><strong>Ouvrir l&#39;éditeur visuel</strong> — bascule vers l&#39;<a href="./visual-editor.html">éditeur visuel</a> pour cette page.</li></ul><h3 id="sections-attachees" tabindex="-1">Sections attachées <a class="header-anchor" href="#sections-attachees" aria-label="Permalink to &quot;Sections attachées&quot;">​</a></h3><p>Chaque section attachée à la page apparaît dans une liste ordonnée, avec :</p><ul><li>une poignée de réordonnancement (glisser-déposer) ;</li><li>une case à cocher <strong>Afficher</strong> — active/désactive l&#39;instance sans la détacher (équivalent de <code>creopse page toggle-section-status</code>) ;</li><li>le nom de la section ;</li><li>un bouton <strong>Données &amp; Paramètres</strong> — édite les données et réglages de cette instance précise de section ;</li><li>un compteur (« X Section(s) ») en bas de liste.</li></ul><p>Le bloc <strong>Insérer ou retirer des sections</strong> permet d&#39;attacher une nouvelle instance de section à la page, ou d&#39;en détacher une existante.</p><div class="tip custom-block"><p class="custom-block-title">Pour les développeurs</p><p>La création de pages et l&#39;attachement de sections (avec <code>link-id</code>, ordre, activation) peuvent aussi être scriptés via la CLI — voir <a href="./../../development/pages.html">Pages</a> et le détail du fonctionnement des sections dans <a href="./../../development/sections-widgets.html">Sections &amp; Widgets</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">Voir aussi</p><p>Une version orientée utilisateur final de cette rubrique existe dans le <a href="./../../../users/sections/content-management.html">Guide Utilisateur</a>.</p></div>',12)])])}const k=i(c,[["render",u]]);export{P as __pageData,k as default};
